static WeakReference Build(Publisher p)
{
    var inner = new List<Subscriber>();
    for (int i = 0; i < 10; i++) inner.Add(new Subscriber(p));
    var wr = new WeakReference(inner[0]);
    Solution.UnsubscribeAll(p, inner);
    inner.Clear();
    return wr;   // helper scope: no strong ref to the subscriber escapes
}
